INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109772, 'spa', 'Un uso único del Hitpael (reflexivo) en 1 Reyes 17', 'Un uso único del Hitpael (reflexivo) en 1 Reyes 17:21, donde Elías ''se tendió sobre'' el hijo muerto de la viuda tres veces antes de que el niño reviviera. La raíz reflexiva desplaza el significado de la medición espacial a la extensión corporal, una acción físico-profética singular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109780, 'spa', 'El sentido dominante', 'El sentido dominante: una unidad estándar de medida, el acto de medir o una cantidad medida — 41 de 54 apariciones. Abarca las especificaciones de las cortinas del tabernáculo (Éx 26:2, 8; 36:9, 15), las leyes levíticas de medida justa (Lv 19:35), las dimensiones del templo de Ezequiel (Ez 40:3, 5; 42:15-19) y usos figurados como ''medida para el viento'' en Job 28:25.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109782, 'spa', 'Una sección delimitada o porción asignada, especialmente de un edificio o territ', 'Una sección delimitada o porción asignada, especialmente de un edificio o territorio — 7 apariciones agrupadas en Nehemías 3 (vv. 11, 19, 20, 21, 24). A cada cuadrilla de reparación del muro se le asigna una middah, un tramo definido para reconstruir. El cambio de medición abstracta a ''porción'' concreta es sutil pero real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109788, 'spa', 'Estatura o altura corporal — 3 apariciones que describen personas de tamaño exce', 'Estatura o altura corporal — 3 apariciones que describen personas de tamaño excepcional. Los espías reportan gigantes como hombres de middot, ''hombres de gran estatura'' (Nm 13:32); el guerrero filisteo tiene dedos de más y es un hombre de middah (1 Cr 20:6); e Isaías 45:14 describe a los altos sabeos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109793, 'spa', 'El tamaño general, la extensión o la amplitud de algo — 2 apariciones en 1 Cróni', 'El tamaño general, la extensión o la amplitud de algo — 2 apariciones en 1 Crónicas 23:29 (los deberes levíticos incluyen la supervisión de ''medidas y tamaños'') y Jeremías 22:14 (Joacim construyendo un palacio ''de amplias dimensiones''). Aquí middah denota la extensión espacial general, no una unidad métrica específica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109794, 'spa', 'Una vestidura o manto — aparición única en Salmo 133', 'Una vestidura o manto — aparición única en Salmo 133:2, donde el aceite de la unción desciende por la barba de Aarón hasta ''el borde de sus vestiduras'' (middotav). La mayoría de los lexicógrafos atribuyen este uso al sustantivo homógrafo mad (vestidura) y no a middah (medida), y la evidencia multilingüe confirma la distinción: el español ''vestiduras'' selecciona claramente vocabulario de indumentaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109802, 'spa', 'Tributo imperial', 'Término fiscal para el tributo o impuesto impuesto por la autoridad imperial, específicamente en el período persa. Sus cuatro apariciones se encuentran en el relato de Esdras sobre las tensiones políticas en torno a la reconstrucción de Jerusalén. Las glosas interlingüísticas («tribute», «tributo») transmiten uniformemente el sentido de pago obligatorio a un poder gobernante, reflejando el vocabulario administrativo del Imperio aqueménida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109807, 'spa', 'Contienda, discordia o riña entre personas, empleada casi exclusivamente en Prov', 'Contienda, discordia o riña entre personas, empleada casi exclusivamente en Proverbios y en la poesía profética para describir conflictos interpersonales destructivos. Proverbios identifica sus fuentes: la ira (15:18; 29:22), el orgullo (28:25), el chisme (16:28) y el temperamento contencioso (26:21), y lo personifica en la figura recurrente de la ''mujer contenciosa'' (21:9; 25:24; 27:15). Habacuc 1:3 aplica el término al desorden que surge en la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109817, 'spa', 'Adverbio interrogativo que significa ''¿por qué?'' o ''¿a causa de qué?'', que indag', 'Adverbio interrogativo que significa ''¿por qué?'' o ''¿a causa de qué?'', que indaga el motivo o la causa detrás de una acción. Se usa en preguntas directas dentro de la narrativa (Gn 26:27; 40:7; Éx 1:18; 2:18; 3:3), en la confrontación y el lamento proféticos (Jer 2:14, 31; 8:5, 19, 22; Is 5:4; 50:2; 63:2) y en preguntas indirectas que expresan perplejidad (Éx 3:3). Probablemente contraído de mah-yadua (''¿qué siendo conocido?'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109819, 'spa', 'Morada o habitación', 'Las glosas identifican consistentemente este término como ''morada, habitación'' con formas posesivas. Daniel 4:25 y 32 describen cómo la morada de Nabucodonosor fue con las bestias del campo durante su juicio, mientras que 5:21 recuerda esta misma humillación para advertir a Belsasar. El énfasis repetido en la morada del rey subraya el tema del orgullo humillado: el monarca poderoso reducido a una existencia animal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109824, 'spa', 'Maday / Media (nombre propio) — El nombre propio Maday — el hijo de Jafet en la ', 'Maday / Media (nombre propio) — El nombre propio Maday — el hijo de Jafet en la Tabla de las Naciones (Gn 10:2; 1 Cr 1:5) — y por extensión el pueblo y territorio de Media (los medos). Usado para las ciudades del exilio medo (2 R 17:6; 18:11), los medos como poder militar convocado contra Babilonia (Is 13:17; 21:2), y el compuesto ''Media y Persia'' que designa el imperio dual (Est 1:3, 14, 18-19; Dn 8:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109832, 'spa', 'Los medos y Media', 'Los medos como pueblo y Media como su territorio. El sentido gentilicio aparece en Daniel 5:28 y 6:8, 12, 15, donde la identidad meda se enfatiza junto a los persas. El territorial aflora en Esdras 6:2, donde se halla un rollo en la provincia de Media. En Génesis 10:2, Madai figura como hijo de Jafet en la tabla de naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109834, 'spa', 'Contienda interpersonal', 'Discordia y contienda entre personas, particularmente como rasgo de carácter que debe evitarse. La evidencia multilingüe («contentions», «disputes», «contiendas») enfatiza consistentemente las disputas continuas más que los conflictos aislados. Proverbios emplea este término para identificar a los alborotadores habituales y prevenir contra su influencia, con especial atención a la discordia doméstica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109835, 'spa', 'Nombre propio que abarca al patriarca, el pueblo y su territorio', 'Nombre propio que abarca al patriarca, el pueblo y su territorio. Las 59 apariciones convergen en un solo referente: ya sea designando reyes y príncipes tribales (Nm 31:8; Jue 7:25), los dromedarios de Madián (Is 60:6) o el territorio mismo (Éx 2:15; Hab 3:7). Las traducciones multilingües — español ''Madián'', francés ''Madian'', alemán ''Midian'' — transliteran uniformemente el nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109843, 'spa', 'provincia, distrito administrativo', 'provincia, distrito administrativo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109857, 'spa', 'Provincia, distrito administrativo', 'Provincia administrativa o distrito gobernado dentro de un gran imperio, particularmente los sistemas babilónico y persa. En Esdras, la provincia «de Más Allá del Río» es la región satrápica que abarca Judá, mencionada en la correspondencia sobre la reconstrucción del templo (Esd 4:15; 5:8; 6:2; 7:16). En Daniel, designa la provincia de Babilonia misma, sobre la cual Daniel recibe autoridad (Dn 2:48-49), y el escenario de la imagen de oro de Nabucodonosor (Dn 3:1-3, 12, 30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109862, 'spa', 'Madianita (gentilicio)', 'Designacion gentilicia para una persona o pueblo de Madian, empleada como adjetivo y como sustantivo. Abarca a los comerciantes madianitas de la narrativa de Jose (Gn 37:28, 36), el vinculo de parentesco a traves del suegro de Moises (Nm 10:29) y los madianitas hostiles del incidente de Baal-Peor (Nm 25:6, 14-15, 17; 31:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109871, 'spa', 'Contienda interpersonal', 'La evidencia multilingüe apunta uniformemente al conflicto interpersonal: en español ''contiendas, discordias''. Proverbios usa este término para caracterizar a quienes ''siembran'' contiendas (6:14, 19), las avivan constantemente (15:18, 28:25, 29:22) y viven en perpetuo conflicto. La ''mujer contenciosa'' se vuelve proverbial (21:9, 25:24, 27:15), al igual que el ''hombre de contiendas'' (26:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109874, 'spa', 'Conocimiento, ciencia, saber', 'Conocimiento, ciencia, saber o erudición: contenido intelectual adquirido y conciencia instruida, que aparece típicamente en paralelismo con חָכְמָה (sabiduría) y דַּעַת (conocimiento). Cinco apariciones abarcan la petición de Salomón de ''sabiduría y conocimiento'' para gobernar Israel (2 Cr 1:10, 11, 12) y los jóvenes exiliados judíos en Babilonia que mostraron aptitud ''en toda ciencia y conocimiento'' (Dan 1:4, 17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109876, 'spa', 'Pensamiento, conciencia interior', 'Pensamiento, mente o conciencia interior: el espacio privado de la conciencia donde se forman opiniones o intenciones. Se encuentra solo en Eclesiastés 10:20: ''ni aun en tu pensamiento (בְּמַדָּעֲךָ) maldigas al rey, porque las aves del cielo llevarán la voz''. El paso del conocimiento público adquirido a la conciencia mental privada queda confirmado por las traducciones pensamiento en español y thoughts en inglés.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109882, 'spa', 'Nombre propio patronímico', 'Nombre propio que identifica al padre de Amán. Las cinco ocurrencias aparecen en Ester dentro de la fórmula patronímica fija que establece el linaje de Amán. La etimología persa (posiblemente de māh, ''luna'') conecta el nombre con las convenciones teofóricas de los nombres iranios. La uniformidad en las traducciones de todas las lenguas confirma su función como identificador personal estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109883, 'spa', '¿qué? (interrogativo)', 'Uso interrogativo central: ''¿qué?'' — pregunta por la identidad, naturaleza o contenido de algo. Con 654 ocurrencias, domina de manera abrumadora. Gn 4:10 (''¿qué has hecho?'') y Gn 3:13 (''¿qué es esto que has hecho?'') son paradigmáticos. Todas las lenguas despliegan su interrogativo básico equivalente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109887, 'spa', '¿con/en qué? (instrumental)', 'Combinado con la preposición beth para preguntar por instrumento, medio o lugar: ''¿con qué?'', ''¿en qué?'' Gn 15:8 (''¿en qué conoceré?'') y Jue 16:5 (''¿con qué se le podría atar?'') son ejemplos clásicos. Las 27 ocurrencias se concentran en diálogos narrativos donde los personajes buscan información práctica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109888, 'spa', '¿cómo? (modo)', 'Uso adverbial que pregunta por el modo: ''¿cómo?'' — indaga sobre la manera en que algo se hace o la naturaleza de una situación. Nm 23:8 (''¿cómo maldeciré al que Dios no ha maldecido?'') emplea מָה donde el español requiere ''cómo''. Gn 28:17 (''¡cuán temible es este lugar!'') oscila entre modo y exclamación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109889, 'spa', '¡cuán! (grado exclamativo)', 'Uso exclamativo que expresa sorpresa, admiración o énfasis sobre el grado: ''¡cuán grande!'', ''¡cuán precioso!'' Concentrado en Salmos y literatura sapiencial — Sal 84:1 (''¡cuán amables!''), Sal 36:7 (''¡cuán preciosa tu misericordia!''). מָה funciona no como pregunta sino como intensificador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109891, 'spa', 'lo que sea (residual/indefinido)', 'Ocurrencias residuales o textualmente inciertas, incluyendo variantes ketiv/qeré y usos indefinidos: ''cualquier cosa'', ''lo que sea''. Job 13:13 (''venga sobre mí lo que sea'') y Prov 9:13 muestran a מָה deslizándose hacia lo indefinido. Is 3:15 (''¿qué pretendéis aplastando a mi pueblo?'') puede comportar fuerza retórica o acusatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109893, 'spa', '¿cuánto? (cantidad)', 'Interrogativo sobre cantidad, número o duración: ''¿cuántos?'', ''¿cuánto?'', ''¿hasta cuándo?'' Gn 47:8 (Faraón preguntando a Jacob ''¿cuántos son los días de tus años?'') y Job 7:19 (''¿hasta cuándo no apartarás de mí tu mirada?'') tipifican este sentido. El hebreo מָה cubre un terreno que muchas lenguas dividen entre ''¿qué?'' y ''¿cuánto?''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109894, 'spa', '¿cuándo? (temporal)', 'Interrogativo temporal: ''¿cuándo?'', ''¿hasta cuándo?'' Sal 74:9 (''¿hasta cuándo, oh Dios?'') y Sal 79:5 (''¿hasta cuándo, Señor?'') son fórmulas de lamento. Las 5 ocurrencias se concentran en salmos de aflicción, lo que convierte este sentido en un uso distintivamente litúrgico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109919, 'spa', '¿por qué? (causa)', 'Interrogativo causal: ''¿por qué?'', ''¿para qué?'' Gn 25:32 (''¿para qué entonces me sirve la primogenitura?'') y Sal 10:13 (''¿por qué desprecia el impío a Dios?'') emplean מָה para indagar la motivación. Solo 2 ocurrencias, lo que sugiere que el hebreo prefirió לָמָּה como interrogativo causal estándar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109921, 'spa', 'El pronombre interrogativo e indefinido «¿qué? / lo que sea»', 'El pronombre interrogativo e indefinido «¿qué? / lo que sea»: pregunta sobre la identidad, naturaleza o contenido, o funciona como relativo indefinido. Abarca tanto preguntas directas como «¿qué has hecho?» (Dn 4:32) como usos relativos: «todo lo que necesitéis» (Esd 6:9) y «Él conoce lo que está en las tinieblas» (Dn 2:22). Es el uso más común de la partícula en el arameo bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109923, 'spa', 'El adverbio exclamativo «¡cuán!» que expresa modo o grado, formado con el prefij', 'El adverbio exclamativo «¡cuán!» que expresa modo o grado, formado con el prefijo כְּ- (kemah). Ambas apariciones se encuentran en la doxología de Nabucodonosor maravillándose ante las señales de Dios: «¡Cuán grandes son sus señales! ¡Cuán poderosas sus maravillas!» (Dn 4:3), donde la partícula intensifica en lugar de interrogar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109924, 'spa', 'El interrogativo causal «¿por qué? / ¿para qué?», formado con el prefijo לְ- (le', 'El interrogativo causal «¿por qué? / ¿para qué?», formado con el prefijo לְ- (lemah). Aparece en Esdras 4:22 advirtiendo a los oficiales contra la negligencia: «¿Por qué habría de crecer el daño?», y en Esdras 7:23 razonando sobre honrar la casa de Dios, donde la pregunta implica consecuencia más que búsqueda de información.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109925, 'spa', 'Demorarse, tardar, vacilar', 'Demorarse, tardar o vacilar — atestiguado solo en Hitpalpel, donde la reduplicación intensifica la idea de espera prolongada. Génesis 19:16 retrata la peligrosa vacilación de Lot; Génesis 43:10 lamenta el tiempo perdido; Éxodo 12:39 explica que Israel no pudo demorarse; y Habacuc 2:3 asegura que la visión no tardará.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109937, 'spa', 'Confusión, tumulto, pánico', 'Confusión repentina y aterradora, o pánico típicamente enviado por Dios, que sume a los ejércitos en desorden o perturba comunidades enteras. Prometida como arma de guerra santa contra los enemigos de Israel (Dt 7:23; Éx 14:24; 23:27), se manifiesta en las derrotas de los filisteos (1 S 5:9, 11; 7:10; 14:20), la batalla escatológica de Zacarías (Zac 14:13) y el juicio profético sobre pueblos rebeldes (Is 22:5; Ez 22:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109944, 'spa', 'Nombre propio bíblico', 'Este nombre propio aparece transliterado como ''Mehetabel, Mehetavel'' en diversas lenguas. La princesa edomita es la única mujer mencionada en la genealogía real de Edom, lo cual sugiere su importancia para preservar dicho linaje. En Nehemías 6:10, el nombre identifica la ascendencia de Semaías, cuya falsa profecía Nehemías resistió con valentía. Ambas apariciones preservan memoria histórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109945, 'spa', 'Hábil y pronto', 'Describe a alguien que es rápido, pronto o diestro en su función, ya sea trabajo de escriba, artesanía o gobierno. Las traducciones multilingües se dividen entre enfatizar la velocidad (''veloz'', ''pronto'') y la habilidad (''diestro'', ''hábil''), reflejando el rango semántico del término. Los contextos sugieren que la prontitud y la competencia eran virtudes estrechamente vinculadas en el pensamiento hebreo antiguo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109948, 'spa', 'Viaje o distancia', 'El acto o la extensión de un viaje, utilizado para medir distancia, duración o espacio arquitectónico. Las traducciones multilingües (''viaje'', ''camino'', ''pasillo'') captan tanto el sentido de travesía como la dimensión espacial. La referencia de Jonás a un ''camino de tres días'' describe el diámetro de la ciudad o el tiempo necesario para atravesarla, mientras que el uso de Zacarías sugiere acceso metafórico a la presencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109950, 'spa', 'Mahalalel (nombre propio)', 'El nombre propio Mahalalel (''alabanza de Dios''), que identifica a dos figuras biblicas: (a) un descendiente de quinta generacion de Adan a traves de Set, cuyo nacimiento, paternidad de Jared y muerte se registran en la genealogia antediluviana formulaica (Gn 5:12-17; 1 Cr 1:2); y (b) un judita postexilico entre los habitantes reasentados en Jerusalen (Neh 11:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109954, 'spa', 'Destrucción catastrófica', 'Destrucción total y catastrófica, usada como sustantivo verbal de la raíz הָפַךְ («derribar, trastornar»). Aparece casi invariablemente en estado constructo dentro de una fórmula comparativa fija que evoca la aniquilación de Sodoma y Gomorra: «como la destrucción de Sodoma» (Deut 29:22; Jer 49:18; Amós 4:11). Cuando Dios es el sujeto, rige un acusativo que expresa juicio divino absoluto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109958, 'spa', 'Cepo punitivo', 'Dispositivo de sujeción o cepo usado como castigo, que obligaba a la víctima a permanecer en una posición incómoda o forzada. Todas las apariciones bíblicas involucran el castigo de profetas o videntes que proclamaron verdades incómodas al poder. Las traducciones multilingües (''stocks'', ''cepo'') lo identifican consistentemente como un instrumento de confinamiento, aunque su mecanismo exacto permanece incierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109959, 'spa', 'apresurarse, darse prisa (Piel)', 'apresurarse, darse prisa (Piel)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109982, 'spa', 'ser precipitado, impetuoso (Nifal)', 'ser precipitado, impetuoso (Nifal)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110002, 'spa', 'rápidamente — Un adverbio de velocidad o premura, sintácticamente ligado al verb', 'rápidamente — Un adverbio de velocidad o premura, sintácticamente ligado al verbo que sigue inmediatamente. Concentrado en Deuteronomio para expresar la rapidez del juicio divino (''pereceréis pronto'', Dt 4:26; 28:20), la ayuda divina en la conquista (''Él los destruirá rápidamente'', Dt 7:4, 22; 9:3) y la alarmante celeridad de la apostasía de Israel con el becerro de oro (Éx 32:8; Dt 9:12, 16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110005, 'spa', 'Dote matrimonial', 'Las traducciones multilingües identifican consistentemente el pago matrimonial: español ''dote, precio de novia''. Éxodo 22:17 establece la norma legal de la dote de las vírgenes. Génesis 34:12 muestra a Siquem dispuesto a pagar cualquier cantidad tras violar a Dina. Notablemente, 1 Samuel 18:25 registra la mortífera exigencia de Saúl de cien prepucios filisteos como precio de novia, en un intento de eliminar a David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110006, 'spa', 'rápidamente, apresuradamente, velozmente — El adverbio מְהֵרָה, ''rápidamente, ap', 'rápidamente, apresuradamente, velozmente — El adverbio מְהֵרָה, ''rápidamente, apresuradamente, con prisa'', que expresa urgencia o velocidad de acción. Típicamente sigue al verbo en prosa (Jos 8:19, la emboscada se levanta rápidamente; 2 S 17:16, 21, David debe huir rápidamente) y lo precede en poesía para un efecto intensificado (Is 5:26; Sal 31:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110010, 'spa', 'Guerrero de David', 'Este nombre propio se transliteró uniformemente como ''Maharai'' en las diversas traducciones. El guerrero provenía de Netofa, un pueblo cercano a Belén. Su inclusión entre los valientes de David (2 Sam 23:28, 1 Cr 11:30) y su nombramiento como comandante de división mensual (1 Cr 27:13) atestiguan su destreza militar y su liderazgo. Representa el núcleo leal de los guerreros que sostuvieron el reinado davídico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110013, 'spa', 'Moab (lugar y pueblo)', 'Nombre propio que designa la tierra al este del mar Muerto, su pueblo (entendido como descendientes de Lot según Gn 19:37) y el reino gobernado por figuras como Balac (Nm 22:4) y Mesá. El término funciona como persona, nación y territorio según el contexto. Jeremías 48 por sí solo suma más de 30 ocurrencias en un extenso oráculo contra Moab. El nombre pasa sin cambios a prácticamente todas las lenguas receptoras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110024, 'spa', 'Moabita (adjetivo/sustantivo gentilicio)', 'Moabita (adjetivo/sustantivo gentilicio): adjetivo y sustantivo gentilicio que identifica a una persona de ascendencia moabita, usado en formas masculinas, femeninas, singulares y plurales. Se vincula de manera prominente con Rut — ''Rut la moabita'' aparece seis veces (Rut 1:22; 2:2, 6, 21; 4:5, 10), poniendo en primer plano su identidad extranjera dentro de un relato de inclusión. El término también marca la exclusión deuteronómica de los moabitas de la asamblea (Dt 23:4; Neh 13:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110032, 'spa', 'Derretirse, disolverse (intransitivo)', 'Derretirse, disolverse (intransitivo): derretimiento o disolución intransitiva — la tierra, los corazones o los pueblos pierden su forma sólida o su determinación. Abarca las raíces Qal intransitiva, Nifal e Hitpael. El Cántico del Mar declara que los pueblos ''se derritieron'' (נָמֹגוּ, Éx 15:15), y Rajab confirma que los habitantes de Canaán perdieron el ánimo (Jos 2:9, 24). El Salmo 46:6 retrata la disolución cósmica ante la voz de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110033, 'spa', 'Hacer derretir, ablandar (causativo)', 'Hacer derretir, ablandar (causativo): derretimiento o ablandamiento causativo — Dios como agente que disuelve o licua algo. En el Salmo 65:10, Dios ablanda la tierra con lluvias (תְּמֹגְגֶנָּה), una imagen agrícola apacible. En contraste, Job 30:22 usa el verbo para describir a Dios disolviendo al propio Job en la tormenta del sufrimiento. Isaías 64:7 puede conservar un sentido causativo similar de Dios derritiendo a su pueblo, aunque el texto es debatido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110049, 'spa', 'Ser sacudido, ser movido', 'Ser sacudido, ser movido: Sentido pasivo Nifal: ser sacudido, ser movido o perturbado de una posición estable. Es la voz de la confianza teológica — la tierra no será movida (1 Cr 16:30), y quien confía en el SEÑOR no será conmovido (Sal 15:5; 16:8). La afirmación negativa ''no seré movido'' (Sal 10:6; 62:2, 6) funciona casi como una fórmula confesional en el Salterio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110054, 'spa', 'Resbalar, perder pie', 'Resbalar, perder pie: Sentido Qal más específico: resbalar o perder el equilibrio, enfatizando la pérdida súbita de tracción más que el bamboleo gradual. Cuando la mano de tu hermano resbale (Lv 25:35), debes sostenerlo. Su pie resbalará a su debido tiempo (Dt 32:35) presenta el juicio divino como un camino traicionero. Los pasos del salmista no han resbalado (Sal 17:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110055, 'spa', 'Hacer caer, derribar', 'Hacer caer, derribar: Causativo Hifil: hacer caer a alguien, derribar o abatir. En el Salmo 140:10, el salmista pide que caigan carbones encendidos sobre los malvados. El Salmo 55:3 pide igualmente que Dios derribe al opresor. Este sentido invierte el patrón pasivo habitual: en lugar de pedir ''no me dejes ser sacudido'', el hablante pide a Dios que sacuda al enemigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110056, 'spa', 'Tambalear, vacilar, tambalearse', 'Tambalear, vacilar, tambalearse: Sentido activo Qal y reflexivo Hitpael: tambalear, vacilar o tambalearse como algo que pierde el equilibrio. Los montes se estremecen cuando Dios se levanta (Sal 46:2, 6), la tierra se tambalea bajo el juicio (Is 24:19-20) y los conducidos al matadero se tambalean indefensos (Pr 24:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110076, 'spa', 'Tambaleo, resbalón', 'Sustantivo abstracto de tambaleo, tropiezo o resbalón, siempre empleado con negación para expresar la seguridad divina. En el Salmo 66:9 Dios «no ha dejado que nuestros pies resbalen», y el Salmo 121:3 promete que no dejará que tu pie se mueva. La imagen cinestésica de un paso inestable es lo que los salmistas niegan de aquellos a quienes Dios protege.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110077, 'spa', 'Pértiga, vara de carga', 'Pértiga o vara de transporte, del tipo que se coloca entre dos portadores para cargar objetos pesados. Números 13:23 describe el racimo de Escol llevado en una de estas varas. Los términos españoles «pértiga» y «vara» captan el sentido concreto del equipo usado en las instrucciones del tabernáculo (Núm 4:10, 12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110078, 'spa', 'Yugo de sujeción', 'Travesaño de un yugo, usado figuradamente para la sujeción política o imperial. Nahúm 1:13 declara que Dios quebrará «su yugo de sobre ti», prometiendo liberación de la dominación asiria. La evidencia multilingüe converge: el español «yugo suyo» y el inglés «his yoke» reflejan la metáfora del cautiverio que será roto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110080, 'spa', 'Barra de yugo', 'Barra de yugo — el travesaño de madera que forma parte de un yugo — usada literalmente para yugos de animales y figuradamente para la opresión política y social. El acto simbólico de Jeremías domina el uso: fabricó barras de yugo y coyundas (Jer 27:2), Hananías quebró la barra de madera (Jer 28:10, 12), y Dios la reemplazó con una barra de hierro (Jer 28:13). Levítico 26:13 recuerda cómo Dios quebró las barras del yugo de Egipto, y Ezequiel 34:27 promete romperlas en liberación futura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110085, 'spa', 'Vara de transporte', 'Vara o pértiga de transporte utilizada para llevar mobiliario sagrado, específicamente las varas insertadas a través de las argollas del Arca de la Alianza. La única aparición en 1 Crónicas 15:15 describe a los levitas cargando el Arca de Dios «con las varas sobre sus hombros, como Moisés había mandado». Aunque comparte la forma básica de barra de madera con el sentido de yugo, el contexto sagrado y la función de transporte lo distinguen claramente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110086, 'spa', 'Empobrecerse progresivamente', 'Reducirse económicamente, caer en la pobreza — describe el proceso de empobrecimiento entre miembros del pacto. Concentrado en la legislación levítica (25:25, 35, 39, 47; 27:8), el verbo activa obligaciones comunitarias: redención de tierras, préstamos sin interés, límites a la servidumbre y ajuste en la valoración de votos. El cognado arameo מוּךְ (''hundirse'') refuerza el matiz de descenso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110087, 'spa', 'Ser circuncidado (Nifal/pasivo)', 'Ser circuncidado (Nifal/pasivo): Sentido Nifal o pasivo: ser circuncidado, someterse a la circuncisión o estar en el estado de haber sido circuncidado. Génesis 17:10-14 establece el requisito del pacto de que todo varón ''sea circuncidado''. Este sentido abarca tanto el rito físico como el estado resultante que marca la pertenencia al pacto con Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110088, 'spa', 'Circuncidar (Qal activo)', 'Circuncidar (Qal activo): Sentido Qal activo: realizar el acto de circuncisión sobre alguien. Abraham circuncidó a su casa (Gn 17:23) y luego a su hijo Isaac al octavo día (Gn 21:4). Deuteronomio 10:16 y 30:6 extienden esto a la metáfora — circuncidar el corazón — donde el corte físico se convierte en figura de la remoción de la obstinación espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110089, 'spa', 'Cortar, destruir (Hifil)', 'Cortar, destruir (Hifil): Sentido causativo Hifil que significa cortar o destruir enemigos, atestiguado solo en el Salmo 118:10-12, donde el salmista declara tres veces: ''¡En el nombre del SEÑOR los destruiré!'' La triple repetición con imaginería escalada (naciones, naciones que rodean, enjambre como abejas) confiere a este uso una fuerza retórica muy distante de la ceremonia del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110096, 'spa', 'Marchitarse, secarse (Piel)', 'Marchitarse, secarse (Piel): Sentido raro que significa marchitarse o secarse, hallado solo en el Salmo 90:6, donde la hierba florece por la mañana y al atardecer ''se marchita y se seca''. Algunos lexicógrafos asignan este uso a una raíz distinta (malal III), pero la tradición textual lo conserva bajo מוּל. La conexión podría residir en la idea compartida de cortar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110112, 'spa', 'Enfrente, frente a, delante de', 'Enfrente, frente a, delante de: Preposición espacial que significa ''enfrente'', ''frente a'' o ''delante de'' — el uso dominante en sus 35 apariciones. Se emplea en instrucciones cultuales para el tabernáculo (Éx 26:9; 28:25, 27, 37), en orientación geográfica (Dt 1:1; 3:29 ''frente a Bet-peor'') y en descripciones arquitectónicas (1 R 7:5). Capta la precisión direccional de situar algo cara a cara con un punto de referencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110121, 'spa', 'Al lado opuesto, enfrente', 'Al lado opuesto, enfrente: Uso direccional que indica ''del lado opuesto'' o ''enfrente'', en Nehemías 12:38 en la forma variante מוֹאֵל. Puede describir la segunda procesión de acción de gracias marchando en dirección contraria a lo largo del muro. El BDB sugiere que la lectura podría ser una corrupción de לִשְׂמֹאל (''a la izquierda''), y la evidencia multilingüe refleja esta incertidumbre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110122, 'spa', 'Ciudad de Simeón', 'Nombre propio de una ciudad en la heredad de Simeón, en el territorio meridional. La evidencia multilingüe preserva el nombre con variación mínima (Moladah, Molada, Moladá), acorde con su función como identificador geográfico. Su aparición tanto en las listas territoriales tempranas como en los registros de asentamiento postexílicos sugiere continuidad de identificación, aunque no necesariamente de ocupación ininterrumpida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110123, 'spa', 'Descendencia, hijos o los nacidos de alguien, la prole en sentido concreto', 'Descendencia, hijos o los nacidos de alguien, la prole en sentido concreto. Jacob dice a José que los hijos nacidos después de Efraín y Manasés serán la ''descendencia'' propia de José (Gn 48:6). El Código de Santidad lo emplea para una hija ''nacida de'' su padre o madre (Lv 18:9, 11), distinguiendo entre hermanos de padre y madre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110124, 'spa', 'El lugar o tierra de nacimiento, la patria o país natal', 'El lugar o tierra de nacimiento, la patria o país natal. Este es el sentido más frecuente, con diez ocurrencias. Dios llama a Abram a dejar su ''tierra natal'' (Gn 12:1), y la patria de Noemí es el destino de Rut (Rut 2:11). La construcción ''eretz moledet'' (tierra de nacimiento/parentela) aparece en Gn 11:28; 24:7 y Jer 46:16.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110125, 'spa', 'Los parientes, la familia extensa o el grupo de personas a las que uno pertenece', 'Los parientes, la familia extensa o el grupo de personas a las que uno pertenece por nacimiento. Cuando el siervo de Abraham pregunta por la familia (Gn 43:7) o cuando Dios ordena a Jacob regresar a su ''parentela'' (Gn 31:3, 13), el término designa la red de relaciones humanas definida por el linaje compartido. Ester oculta su ''parentela'' (Est 2:10, 20), es decir, su pueblo e identidad familiar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110126, 'spa', 'El evento o las circunstancias del nacimiento en sí, la natividad u origen como ', 'El evento o las circunstancias del nacimiento en sí, la natividad u origen como concepto abstracto. Este sentido raro aparece en la alegoría de Ezequiel sobre los orígenes de Jerusalén: ''tus nacimientos y tu natividad son de la tierra del cananeo'' (Ez 16:3-4), donde el plural evoca vívidamente las sórdidas condiciones de la fundación de la ciudad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110142, 'spa', 'Engastado o rodeado', 'Describe objetos rodeados, encerrados en monturas o posicionados dentro de un marco. Los contextos sacerdotales enfatizan gemas montadas en oro (''engastadas'', ''monturas cerradas''), mientras que el uso arquitectónico de Ezequiel sugiere elementos giratorios o pivotantes. La evidencia multilingüe muestra variación (''rodeadas'', ''giratorias'', ''engastadas''), reflejando la aplicación del término tanto a encierros estáticos como a mecanismos de rotación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110143, 'spa', 'Cimiento o fundamento', 'Las traducciones multilingües identifican de manera uniforme ''fundamento, cimiento''. En 2 Crónicas 8:16 la colocación de los cimientos marca un hito crucial en el proyecto constructivo de Salomón, desde el cimiento hasta la terminación. Isaías 28:16 emplea la imagen del fundamento para la promesa mesiánica de Dios: una piedra angular probada y preciosa en Sion. Ezequiel 41:8 describe los cimientos del templo visionario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110146, 'spa', 'Fundamento (base estructural)', 'Los cimientos cósmicos o geológicos de la tierra y las montañas, concebidos como la capa estructural más profunda de la creación que solo Dios estableció y que tiembla ante su presencia teofánica. Los cimientos del cielo se estremecen (2 Sam 22:8), los fundamentos del mundo quedan al descubierto (2 Sam 22:16; Sal 18:7, 15), el fuego consume hasta los cimientos (Deut 32:22) y los cimientos de la tierra atestiguan contra el pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110151, 'spa', 'Ataduras, cadenas, ligaduras', 'Ataduras, cadenas o cuerdas literales usadas para confinar a una persona o animal. Dios saca a los prisioneros de las tinieblas y rompe sus cadenas de hierro (Sal 107:14). El asno montés es liberado de sus ataduras para vagar por el desierto (Job 39:5). Se ordena a Jeremías fabricar barras de yugo y ataduras como acto profético (Jer 27:2). La imagen física de cuerda o cadena subyace a todas las extensiones figuradas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110161, 'spa', 'disciplina e instrucción moral', 'disciplina e instrucción moral');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110163, 'spa', 'corrección y castigo', 'corrección y castigo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110171, 'spa', 'advertencia y amonestación', 'advertencia y amonestación');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110173, 'spa', 'instrucción didáctica', 'instrucción didáctica');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110174, 'spa', 'atadura o restricción', 'atadura o restricción');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110181, 'spa', 'reunión (tienda de reunión)', 'El lugar designado de encuentro con Dios, que aparece abrumadoramente en la fórmula אֹהֶל מוֹעֵד (''tienda de reunión''). Esto representa aproximadamente dos tercios de todas las ocurrencias y satura los libros de Éxodo a Números. El árabe al-ijtimāʿ (''la reunión'') y el suajili mkutano (''encuentro'') preservan la dimensión comunitaria: no se trata de audiencia privada sino de encuentro congregacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110182, 'spa', 'tiempo señalado', 'Un punto fijo o designado en el tiempo, sin referencia específica a festividades ni al tabernáculo. Dios promete a Abraham un hijo ''al tiempo señalado'' (Gn 18:14), y Samuel indica a Saúl que espere hasta ''el tiempo señalado'' (1 S 13:8). El árabe mīʿād/mawʿid (''cita/fecha'') captan esto con precisión. El énfasis recae sobre la programación divina o autoritativa: algo determinado, no accidental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110184, 'spa', 'fiesta señalada, festividad', 'Las fiestas religiosas señaladas y las estaciones sagradas, como en Levítico 23:2 donde Dios declara ''estas son mis fiestas señaladas.'' El árabe mawsim (''estación/festival'') confirma el sentido calendárico y celebratorio. Estos moadim estructuran el año litúrgico de Israel: Pascua, Semanas, Tabernáculos y las asambleas solemnes. Zacarías 8:19 vislumbra un día en que los ayunos se convertirán en fiestas gozosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110195, 'spa', 'señal convenida', 'Una única ocurrencia en Jueces 20:38 donde מוֹעֵד denota una ''señal convenida'' — un signo pactado de antemano entre las fuerzas de emboscada israelitas y el ejército principal. Esto extiende el núcleo semántico de ''lo señalado'' desde el tiempo y el lugar hacia una comunicación preestablecida, mostrando la flexibilidad de la palabra dentro de su significado raigal de designación divina o humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110196, 'spa', 'lugar de reunión', 'Una ubicación designada para asamblea o encuentro, fuera de la fórmula ''tienda de reunión.'' En Josué 8:14, los hombres de Hai salen ''al lugar señalado,'' y en el Salmo 74:4,8 el enemigo destruye los ''lugares de reunión'' de Dios. Estas pocas ocurrencias muestran que מוֹעֵד puede denotar cualquier punto de congregación sagrado o significativo, no solo el tabernáculo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110241, 'spa', 'Consejos, planes, deliberaciones', 'Consejos, planes o deliberaciones, predominantemente en contextos de maquinacion humana contra la voluntad de Dios. En los Salmos 5:10 y 81:12 el salmista pide a Dios que juzgue o abandone a las personas a sus propios consejos; Proverbios 1:31 advierte que los necios comeran el fruto de sus propias tramas; Jeremias 7:24 vincula el termino con la rebelion obstinada. Solo Proverbios 22:20 lo usa en sentido positivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110249, 'spa', 'Ciudad levítica rubenita', 'Ciudad levítica en territorio de Rubén, situada posteriormente en Moab. Josué 13:18 la incluye entre las ciudades de Rubén, Josué 21:37 y 1 Crónicas 6:64 la identifican como asignación levítica, y Jeremías 48:21 la menciona entre las ciudades moabitas bajo juicio. La variación ortográfica en los manuscritos hebreos (visible en diferencias ketiv/qeré) atestigua una transmisión textual compleja.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110250, 'spa', 'Prodigio, milagro', 'Prodigio, milagro: Sentido principal: un prodigio o milagro, un acto sobrenatural que demuestra el poder divino. Aparece casi siempre emparejado con ''señales'' (אוֹתוֹת) en recuerdos formulaicos del éxodo: ''señales y prodigios'' (Dt 4:34; 6:22; 7:19; 26:8; 34:11; Sal 78:43; 105:27). Las plagas ante Faraón (Éx 7:3; 11:9-10), los portentos cósmicos de Joel (Jl 2:30) y la alabanza retrospectiva del salmista pertenecen a este ámbito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110255, 'spa', 'Señal, símbolo', 'Señal, símbolo: Señal o símbolo que autentica un mensaje profético o apunta a una realidad divina. El varón de Dios da una ''señal'' de que el altar se partirá (1 R 13:3, 5), Ezequías recibe una señal confirmatoria (2 Cr 32:24) y figuras proféticas sirven como símbolos vivientes — a Ezequiel se le dice ''yo soy vuestro portento'' (Ez 12:6, 11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110262, 'spa', 'Presagio, augurio', 'Presagio, augurio: Portento o presagio dirigido hacia el futuro, donde una persona o evento prefigura el juicio divino. Deuteronomio 28:46 advierte que las maldiciones del pacto serán ''por señal y por prodigio sobre tu descendencia para siempre''. El Salmo 71:7 registra ''he sido como un portento para muchos'', e Isaías 20:3 designa la acción simbólica de Isaías como ''portento'' contra Egipto y Cus.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110274, 'spa', 'Manantial, fuente o nacimiento de agua', 'Manantial, fuente o nacimiento de agua: el lugar de donde el agua ''sale'' de la tierra. Sal 107:33-35 contrasta convertir manantiales en desierto y desierto en manantiales. Job 28:1 extiende la imagen a una mina, el lugar de donde la plata ''sale'', ampliando el concepto de fuente al origen mineral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110276, 'spa', 'El punto de salida o término de un límite geográfico, empleado en descripciones ', 'El punto de salida o término de un límite geográfico, empleado en descripciones territoriales. Nm 33:2 registra dos veces los ''puntos de partida'' y etapas de Israel; Ez 42:11 describe las salidas de las cámaras del templo. Este uso cartográfico se concentra en Números, Josué y Ezequiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110278, 'spa', 'Lo que sale de la boca', 'Lo que sale de la boca: una palabra pronunciada, un voto o una declaración divina. Dt 8:3 declara que el hombre vive de todo lo que sale de la boca de Dios, versículo que Jesús cita en su tentación en el desierto. Nm 30:12 lo aplica a la fuerza vinculante de un voto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110280, 'spa', 'El acto de salir o emerger, ya sea de personas, del sol o de un decreto profétic', 'El acto de salir o emerger, ya sea de personas, del sol o de un decreto profético. Sal 19:6 describe la ''salida'' del sol desde un extremo del cielo. Dn 9:25 marca la historia desde la ''salida'' de un decreto para reconstruir Jerusalén. Os 6:3 compara la venida de Dios con la aurora que emerge.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110282, 'spa', 'El oriente como lugar de donde el sol ''sale''', 'El oriente como lugar de donde el sol ''sale''. Sal 75:6 afirma que la exaltación no viene ni del oriente ni del occidente. Este uso direccional especializado deriva naturalmente del sentido 4 (amanecer como salida), pero está lexicalizado como punto cardinal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110295, 'spa', 'Vegetación o brote que ''sale'' de la tierra', 'Vegetación o brote que ''sale'' de la tierra. Job 38:27 pregunta quién hace que el ''brote'' de hierba tierna germine. Esta extensión botánica de ''salir'' es un uso hapax dentro de la distribución del lema, aplicando la metáfora raíz a la germinación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110299, 'spa', 'Letrina o lugar de necesidades', 'Letrina o lugar de necesidades: el sitio al que uno ''sale'' para el alivio corporal. 2 R 10:27 registra que los hombres de Jehú demolieron el templo de Baal y lo convirtieron en letrinas. Este uso crudo pero vívido explota el sentido de ''salir'' en su aplicación más física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110302, 'spa', 'Nombre propio bíblico', 'Nombre propio para dos individuos en Crónicas. En 1 Crónicas 2:46, Motsa es un calebita a través de la concubina Efa. En 1 Crónicas 8:36-37 y su paralelo 9:42-43, Motsa es un benjaminita descendiente de Saúl por medio de Merib-baal. Las variantes de la LXX (Ioosa, Maisa, Massa, Mosa) sugieren confusión temprana o variación dialectal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110304, 'spa', 'Estrechez y angustia', 'La evidencia interlingüística apunta a constricción y angustia: español ''estrechez, angustia''. Job 36:16 promete liberación de la angustia hacia un lugar amplio de libertad. Job 37:10 lo usa para la constricción del hielo, cuando el agua se solidifica. Isaías 9:1 recuerda la aflicción histórica infligida a los territorios del norte por la invasión asiria, contrastándola con la luz venidera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110305, 'spa', 'Fundición o masa compacta', 'Las traducciones identifican fundición y moldeo: en español «fundido», en francés «jeté». En 1 Reyes 7:23, 37 se describe la impresionante obra en bronce del templo de Salomón, donde el enorme mar y las bases fueron fundidos como piezas únicas, un logro metalúrgico notable. Job 38:38 emplea la imagen del polvo compactado en terrones duros, quizá comparando la solidez de la tierra con el metal fundido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110310, 'spa', 'Cebo o dispositivo de disparo en la trampa de un cazador, usado literalmente par', 'Cebo o dispositivo de disparo en la trampa de un cazador, usado literalmente para la caza de aves (Am 3:5) pero abrumadoramente figurado para todo lo que atrae hacia la ruina. Se aplica a la idolatría cananea como trampa perenne de Israel (Éx 23:33; 34:12; Dt 7:16; Jos 23:13; Jue 8:27), a las conspiraciones enemigas contra los justos (Sal 18:5; 140:5; 141:9) y a la necedad humana: el hablar imprudente (Pr 18:7), los votos apresurados (Pr 20:25) y el temor al hombre (Pr 29:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110324, 'spa', 'Intercambiar o sustituir una cosa por otra (Hifil)', 'Intercambiar o sustituir una cosa por otra (Hifil). Levítico 27:10 y 27:33 prohíben sustituir un animal consagrado al sacrificio. Salmo 106:20 pronuncia una acusación devastadora: ''cambiaron su Gloria por la imagen de un buey que come hierba''. Oseas 4:7 advierte que Dios cambiará su gloria por vergüenza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110326, 'spa', 'Ser cambiado o alterado (Nifal pasivo)', 'Ser cambiado o alterado (Nifal pasivo). Jeremías 48:11 compara a Moab con vino reposado sobre sus sedimentos: ''su sabor no ha sido cambiado'' (לֹא נָמָר). Esta única aparición en Nifal pasa del acto deliberado del intercambio al estado de permanecer inalterado: Moab nunca fue al exilio, así que su carácter permanece sin cambio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110337, 'spa', 'Temor, pavor, terror', 'Temor, pavor o terror abstracto experimentado por otros o impuesto sobre ellos. Se usa para el miedo que los animales tienen del ser humano (Gén 9:2), el pavor que precede el avance de Israel (Deut 11:25) y el gran terror del Éxodo (Deut 26:8; 34:12). Isaías 8:12 advierte contra temer lo que el pueblo teme. Es la emoción cruda del espanto, emparejada frecuentemente con sinónimos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110340, 'spa', 'Terrores, hechos portentosos', 'Hechos aterradores o espectáculos sobrecogedores, un uso concreto en plural. Deuteronomio 4:34 pregunta si algún dios intentó tomar una nación ''con grandes terrores'' — los actos poderosos de las plagas y el cruce del Mar Rojo. Las traducciones al español emplean ''terrores'' para designar estos eventos espantosos específicos, distinguiéndolos de la emoción abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110342, 'spa', 'El Temible (epíteto divino)', 'El Temible, epíteto divino sustantivado que designa a Dios como objeto legítimo de reverencia. El Salmo 76:11 llama a los adoradores a traer ofrendas ''al Temible''. Este sentido trasciende la mera emoción para entrar en la teología: el temor se convierte en nombre propio, identificando a Dios por la respuesta que Él legítimamente exige.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110349, 'spa', 'Trillo agrícola', 'Las traducciones identifican uniformemente el implemento de trilla: en español «trillos». La generosa oferta de Arauna a David incluía no solo la era sino también los trillos de madera y los bueyes para el sacrificio (2 Sam 24:22, 1 Cr 21:23). Isaías 41:15 transforma esta herramienta agrícola en una poderosa metáfora: Israel será el trillo nuevo y afilado de Dios para desmenuzar montañas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110350, 'spa', 'Pendiente geográfica', 'Pendiente o declive geográfico por el que ocurre movimiento descendente. Josué 10:11 describe la bajada de Bet-horón donde Dios lanzó granizos sobre los amorreos, y Josué 7:5 nombra la bajada cerca de Sebarim durante la derrota de Israel. Jeremías 48:5 menciona la bajada de Horonaim en el oráculo contra Moab, y Miqueas 1:4 lo emplea como símil de agua precipitándose.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110351, 'spa', 'Lluvia temprana', 'Las traducciones identifican la lluvia estacional: en español «lluvia temprana». El Salmo 84:6 describe poéticamente la lluvia temprana como bendición divina que cubre la tierra. Joel 2:23 menciona dos veces que Dios restaura la lluvia temprana «en justicia» o «como antes», señalando el fin del juicio de sequía y el retorno de la bendición agrícola. Estas lluvias, junto con las tardías, constituyen el ciclo completo de fertilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110352, 'spa', 'Topónimo sagrado', 'Este topónimo aparece transliterado como «Moré» en las distintas lenguas. La encina de Moré cerca de Siquem (Gn 12:6, Dt 11:30) marca la primera parada de Abraham en la tierra prometida, un sitio sagrado asociado con revelación divina. El collado de Moré (Jue 7:1) sirvió como campamento de los madianitas frente a las fuerzas de Gedeón. Ambos sitios comparten la designación de «maestro», sugiriendo que eran lugares reconocidos de oráculo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110353, 'spa', 'Navaja ritual', 'Las traducciones identifican uniformemente el instrumento de afeitar: en español «navaja». La frase idéntica «no pasará navaja sobre su cabeza» aparece en los tres contextos. Ana consagra a su hijo Samuel como nazareo (1 Sam 1:11). El ángel ordena que Sansón sea consagrado desde el vientre (Jue 13:5), y Sansón revela este secreto a Dalila (16:17), explicando que cortar su cabello quebraría su voto y su fuerza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110356, 'spa', 'Posesión o herencia', 'Las traducciones apuntan a posesión y herencia. Isaías 14:23 retrata la inversión total de Babilonia: de imperio a hábitat de erizos, posesión de criaturas salvajes. Abdías 1:17 promete la restauración donde Jacob reclamará lo que legítimamente le pertenece. Job 17:11 emplea el término metafóricamente para designar los anhelos más preciados del corazón. El vocablo abarca tanto la propiedad material como los deseos atesorados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110357, 'spa', 'Posesión / herencia territorial', 'Posesión o herencia referida específicamente a la tierra recibida como concesión divina o patrimonio nacional. En Éxodo 6:8, Dios juró entregar la tierra como מוֹרָשָׁה a los descendientes de Abraham. Deuteronomio 33:4 extiende el concepto a la Torá misma como posesión colectiva. En Ezequiel, naciones hostiles reclaman la tierra de Israel como su propia heredad, provocando juicio profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110363, 'spa', 'Apartarse, alejarse (Qal)', 'Apartarse, alejarse (Qal): Qal intransitivo: apartarse, alejarse o retirarse de un lugar, persona o norma. El énfasis está en algo que abandona su puesto, frecuentemente negado para expresar constancia — ''el arca no se apartó'' (Éx 33:11), ''no se apartará de tu boca'' (Jos 1:8). Números 14:44 registra que el arca ''no se movió'' cuando Israel presumió avanzar sin Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110368, 'spa', 'Apartarse, cesar (Hifil intransitivo)', 'Apartarse, cesar (Hifil intransitivo): Hifil usado intransitivamente, significando apartarse o cesar, donde la raíz Hifil añade énfasis o formalidad sin introducir un agente separado. Job 23:12 declara ''no me he apartado del mandamiento de sus labios,'' y el Salmo 55:11 lamenta que la opresión no ''cesa'' de la plaza de la ciudad. Éxodo 13:22 nos dice que la columna de nube no se retiró de delante del pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110371, 'spa', 'Remover, quitar (Hifil causativo)', 'Remover, quitar (Hifil causativo): Hifil causativo: remover o quitar algo activamente, con un agente explícito realizando la acción. Miqueas 2:3 advierte que el pueblo de Dios no ''quitará sus cuellos'' del yugo venidero del juicio, y Zacarías 3:9 promete ''quitaré la iniquidad de esta tierra en un solo día.'' Pasajes clave: Miqueas 2:3-4, Zacarías 3:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110383, 'spa', 'Morada, asentamiento', 'Morada, asentamiento: Sentido dominante: lugar de residencia, asentamiento, habitación o morada donde individuos o comunidades viven. Aparece en resúmenes genealógicos que listan los territorios de los clanes (Gn 10:30, ''su morada fue desde Mesa''), en la ley del pacto que especifica regulaciones para ''todas vuestras moradas'' (Éx 12:20) y en visiones proféticas de restauración (Ez 34:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110388, 'spa', 'Asiento, silla', 'Asiento, silla: Asiento o lugar para sentarse, particularmente en un contexto oficial, judicial o ceremonial. En 1 Samuel 20:18, 25, Jonatán advierte a David que su asiento (מוֹשָׁב) en la mesa del rey quedará visiblemente vacío; en 1 Reyes 10:5 la reina de Sabá se maravilla del ''asiento de sus siervos''. El Salmo 1:1 extiende el sentido al ''asiento de los escarnecedores''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110394, 'spa', 'Ubicación, situación', 'Ubicación, situación: Caso en 2 Reyes 2:19 donde el término designa la ubicación o situación de una ciudad — a Eliseo se le dice ''la ubicación de la ciudad es buena, pero las aguas son malas''. Sugiere un sentido espacial más abstracto: no solo dónde se habita, sino el emplazamiento geográfico o la situación de un lugar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110397, 'spa', 'Moradores, casa', 'Moradores, casa: Aparición en 2 Samuel 9:12 donde el término parece designar el hogar o círculo doméstico de Mefiboset — los que habitan con o pertenecen a la casa de una persona. Apunta a un sentido colectivo de ''moradores'', tratando el sustantivo como metonimia del lugar por quienes lo habitan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110416, 'spa', 'Musi (nombre propio)', 'Nombre propio que identifica a un levita, hijo de Merari y ancestro del clan musita. Sus ocho apariciones se encuentran en contextos genealógicos o censales que enumeran las familias levíticas (Éx 6:19; Nm 3:20; 1 Cr 6:19, 47; 23:21, 23; 24:26, 30). Las traducciones al español y al inglés lo transliteran uniformemente como «Musi». El nombre posiblemente derive de una raíz que significa «retirar» o «apartar».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110421, 'spa', 'morir (Qal general)', 'El sentido Qal no marcado que cubre toda muerte intransitiva: muerte natural (genealogías de Gn 5: ''y murió''), peste, hambruna, muerte en batalla y mortalidad general. Gn 5:5 (''y murió'') establece el estribillo de la mortalidad humana. Es el sentido prototípico del verbo, confirmado por las traducciones básicas de ''morir'' en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110424, 'spa', 'ser ejecutado (Hofal)', 'El Hofal pasivo que expresa la ejecución judicial: ''será muerto''. Se encuentra predominantemente en los códigos legales de Éxodo–Deuteronomio (Éx 21:12–17), donde se prescribe la pena capital comunitaria. Las traducciones emplean construcciones pasivas —''morirá'', ''sera mis à mort''— reflejando con precisión la morfología del Hofal hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110425, 'spa', 'ciertamente morirá (fórmula)', 'La fórmula enfática מוֹת יוּמָת (infinitivo absoluto Qal + yiqtol), traducida ''de cierto morirá'', que marca pronunciamientos solemnes divinos o legales. Oída por primera vez en Gn 2:17 como advertencia de Dios a Adán, reaparece a lo largo del derecho pactual (Gn 26:11; Éx 19:12). Las traducciones emplean adverbios enfáticos: ''ciertamente'', ''certainement'', ''des Todes''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110446, 'spa', 'los muertos (participio)', 'El participio Qal usado sustantivamente para designar ''los muertos, un difunto, un cadáver''. La negociación de Abraham por la sepultura de Sara (Gn 23:3–8) repite cinco veces ''mi muerta'', estableciendo un tierno modismo para el fallecido. Este uso tiende un puente entre verbo y sustantivo, entre la persona y sus restos mortales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110466, 'spa', 'matar (Hifil causativo)', 'El Hifil causativo que significa ''matar, dar muerte, hacer morir'', con un agente activo que ejecuta la acción. A diferencia del Hofal (pasivo), aquí un sujeto actúa: Dios amenaza (Éx 4:24), los hermanos conspiran (Gn 37:18), un rey ordena (2 S 1:15). Las lenguas emplean sus formas causativas estándar de ''matar'', distinguiéndolo claramente del intransitivo ''morir''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110490, 'spa', 'matar (Piel/Polel intensivo)', 'La conjugación intensiva Piel/Polel que denota una matanza vigorosa o enfática, atestiguada en solo tres pasajes (1 S 14:13; 2 S 1:16; 2 R 17:26). La fuerza intensiva implica una matanza repetida o consumada que va más allá de la simple causación. Las traducciones usan verbos activos de matar, en paralelo con el Hifil pero con aspecto intensificado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110492, 'spa', 'muerte (infinitivo nominal)', 'El infinitivo constructo Qal funcionando como sustantivo abstracto con el significado de ''muerte, el morir''. Aparece en expresiones como ''a la muerte de'' (Jue 2:19), ''su morir'' (1 S 4:20) y ''mi muerte'' (Gn 27:2). Solo ocho apariciones, pero de gran peso teológico, conservando la forma nominal cognada presente en todas las lenguas semíticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110551, 'spa', 'Notación musical incierta', 'La evidencia interlingüística revela incertidumbre: las traducciones oscilan entre transliteraciones como «Almut, Mut-labén» y versiones interpretativas como «muerte». El Salmo 9:1 contiene la frase completa en su sobrescrito, probablemente como instrucción de ejecución hoy perdida. El Salmo 48:14 podría contener un término relacionado. Estas anotaciones técnicas atestiguan la rica herencia musical del culto israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110553, 'spa', 'morir (evento físico)', 'La muerte como suceso físico de morir: cesar de vivir. Es la acepción dominante con 107 apariciones, abarcando muertes naturales, violentas y referencias a los decesos de individuos con nombre. Construcciones clave incluyen יוֹם מָוֶת (''día de la muerte'', Gn 27:2), שְׁנַת מָוֶת (''año de la muerte'', Is 6:1) y עַד מָוֶת (''hasta la muerte'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110555, 'spa', 'muerte personificada', 'La muerte como potencia cósmica personificada, frecuente en textos poéticos y proféticos. El Faraón suplica a Moisés que retire ''esta muerte'' como si fuera un agente viviente (Éx 10:17), y Deuteronomio presenta el célebre par ''vida y muerte'' como fuerzas enfrentadas. El uso del artículo definido en múltiples lenguas confirma la elevación retórica de esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110556, 'spa', 'muerte como estado', 'La muerte como condición permanente o ámbito de los muertos, un dominio del que se puede ser liberado o en el que se permanece atrapado. El árabe fī-l-mawt y el francés dans la mort confirman la lectura locativa. Aparece en Job 5:20 (''te redimirá de la muerte'') y en la imaginería de las trampas de la muerte (Sal 18:4-5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110558, 'spa', 'muerte como pena', 'La muerte como castigo judicial, destino decretado o consecuencia impuesta: ser ''entregado a la muerte'' por decreto divino o real. El español a la muerte y el alemán für Tod marcan la dimensión judicial-finalista. Aparece en contextos de sentencia capital (2 S 15:21) y liberación divina de la ejecución (Sal 68:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110560, 'spa', 'muerte como comparación', 'La muerte como parámetro de comparación en símiles y analogías: algo que es ''como la muerte'' o se mide contra ella. Las partículas comparativas (כְּ, כְּמוֹ) marcan el registro figurativo. Nm 16:29 pregunta si los rebeldes morirán ''la muerte de todo hombre'', y el corazón de Nabal queda ''como piedra'', muerto en vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110592, 'spa', 'muertes (plural intensivo)', 'El constructo plural מוֹתֵי (''muertes de'') en Ez 28:10, describiendo las ignominiosas ''muertes de los incircuncisos''. Este plural raro intensifica el concepto: no una simple muerte, sino una calidad de morir asociada con la vergüenza y el juicio divino contra el príncipe de Tiro. Puede tratarse de un plural abstracto-intensivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110595, 'spa', 'Abundancia y ventaja', 'Las traducciones multilingües muestran dos facetas: abundancia material (ganancia, provecho) y ventaja cualitativa. Proverbios 14:23 y 21:5 prometen que el esfuerzo diligente produce abundancia mientras que los atajos llevan a la pobreza. Eclesiastés 3:19 plantea la inquietante pregunta de si la humanidad tiene alguna ventaja sobre las bestias, pues ambos mueren y vuelven al polvo. El término tiende un puente entre lo económico y lo existencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110596, 'spa', 'altar sacrificial', 'Instalación cúltica para la presentación de sacrificios animales, ofrendas de cereal o incienso. Abarca los altares patriarcales al aire libre (Gn 8:20; 12:7), el altar de bronce para holocaustos y el de oro para incienso del Tabernáculo (Éx 27:1; 30:1), el altar del Templo de Salomón, y los altares ilegítimos a dioses extranjeros cuya demolición se ordena.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110646, 'spa', 'Nombre propio edomita', 'Este nombre propio aparece transliterado como «Miza» o «Mizzah» en las diversas traducciones. Génesis 36:13, 17 lo incluye entre los hijos de Reuel y lo identifica como jefe de clan (aluf) en Edom, representando una subdivisión de los descendientes de Esaú. Primera de Crónicas 1:37 repite su nombre en la genealogía paralela. Estos registros genealógicos documentan cómo ambos hijos de Isaac fundaron naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110648, 'spa', 'Jamba de puerta', 'Jamba de puerta: el poste vertical lateral del marco de una puerta o portón. Central en el relato de la Pascua, donde los israelitas marcaron sus jambas con sangre de cordero como señal de protección (Éx 12:7, 22–23). También prominente en el mandamiento del Shemá de inscribir las palabras de Dios en las jambas de la casa (Dt 6:9; 11:20), origen de la tradición de la mezuzá. En contextos arquitectónicos, describe los postes estructurales del templo de Salomón y del santuario visionario de Ezequiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110662, 'spa', 'Herida o llaga incurable', 'Las traducciones identifican uniformemente heridas o llagas. Jeremías 30:13 describe la condición desesperada de Judá: una herida sin medicina sanadora, sin nadie que la vende, que exige intervención divina. Oseas 5:13 usa la metáfora dos veces: Efraín vio su enfermedad y Judá su llaga, pero ni Asiria ni poder humano alguno podían sanar estas heridas. Solo el arrepentimiento y la misericordia de Dios ofrecen restauración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110666, 'spa', 'Garfios sacrificiales', 'Garfios o trinchantes para manipular las ofrendas sobre el altar. Las cinco referencias bíblicas los sitúan en inventarios de utensilios cúlticos: tres en los textos sacerdotales del tabernáculo (Ex 27:3; 38:3; Nm 4:14) y dos en registros del templo (1 Cr 28:17; 2 Cr 4:16). Aparecen junto a paletas, tazones y braseros como equipo estándar del altar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110668, 'spa', 'Discreción, prudencia', 'Discreción, prudencia: discreción, prudencia o facultad de deliberación sabia — el polo positivo, concentrado enteramente en el vocabulario sapiencial de Proverbios. Cinco apariciones emparejan מְזִמָּה con conocimiento (דַּעַת, Pr 1:4; 5:2), entendimiento (תְּבוּנָה, Pr 2:11) y sagacidad (תּוּשִׁיָּה, Pr 3:21). El sabio recomienda la discreción como virtud protectora: ''La discreción te guardará, el entendimiento te protegerá.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110669, 'spa', 'Maquinación perversa, intriga', 'Maquinación perversa, intriga: esquema malvado, intriga perversa o complot malicioso tramado contra los inocentes — el polo negativo del rango moral de מְזִמָּה. Nueve apariciones se concentran en los Salmos y la queja sapiencial: ''el malvado en su orgullo persigue al pobre; que sean atrapados en las tramas que han urdido'' (Sal 10:2). Véase también Sal 21:11 y Sal 139:20, donde los enemigos invocan el nombre de Dios con propósito malvado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110670, 'spa', 'Propósito, plan, pensamiento', 'Propósito, plan, pensamiento: propósito, plan o intención deliberada — moralmente neutral, describiendo los designios de Dios o de los humanos sin juicio ético inherente. Cinco apariciones incluyen la confesión de Job: ''ningún propósito tuyo puede ser frustrado'' (Job 42:2), y la fórmula profética de Jeremías donde la ira de Dios cumple ''los propósitos de su corazón'' (Jer 23:20; 30:24; 51:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110684, 'spa', 'salmo, composición musical litúrgica', 'salmo, composición musical litúrgica');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110685, 'spa', 'Podadera para vides', 'Cuchillo curvo o gancho utilizado para podar vides y cortar brotes (Isaías 18:5). Las traducciones multilingües («pruning hooks», «podaderas», «serpette») lo identifican consistentemente como herramienta hortícola. En la literatura profética se transforma en símbolo: la conversión de armas en herramientas de labranza representa el establecimiento de la paz de Dios, mientras que lo inverso simboliza la preparación para el juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110686, 'spa', 'Despabiladeras del templo', 'Despabiladeras o cortamechas del templo para el mantenimiento del candelabro. En 1 Reyes 7:50 y 2 Crónicas 4:22 figuran como enseres de oro del templo de Salomón. Los relatos de la deportación (2 R 25:14; Jer 52:18) registran su confiscación como objetos de bronce, y 2 Reyes 12:13 las excluye de los gastos de reparación del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110687, 'spa', 'Diminutivo enfático', 'Diminutivo enfático que significa «muy poco» o «extremadamente pequeño», intensificando la palabra ordinaria para «poco» (מְעַט). Todas las ocurrencias se encuentran en Isaías, donde subraya la brevedad del tiempo antes de que Dios actúe o el tamaño ínfimo del remanente superviviente. El término marca momentos de urgencia retórica en los que lo mínimo cobra máxima importancia profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110691, 'spa', 'este, punto cardinal', 'este, punto cardinal');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110693, 'spa', 'salida del sol', 'salida del sol');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110722, 'spa', 'Tazón o cuenco sacrificial', 'Tazón o cuenco sacrificial: Tazón o cuenco ritual usado para recoger, contener y rociar sangre sacrificial o presentar ofrendas. Nombrado a partir de זָרַק (''arrojar/rociar''), es equipo estándar del altar (Éx 27:3; 38:3; Nm 4:14). Doce tazones de plata llenos de ofrendas de grano dominan la dedicación tribal en Números 7. El templo de Salomón tenía versiones en bronce y oro (1 R 7:40-50). Amós 6:6 condena el uso secular abusivo de estos recipientes sagrados para el festín lujoso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110738, 'spa', 'Aplaudir con gozo', 'La evidencia multilingüe apunta uniformemente al gesto de batir palmas: español ''aplaudir, batir palmas''. El Salmo 98:8 personifica a los ríos aplaudiendo ante la venida de Dios para juzgar la tierra. Isaías 55:12 imagina a los árboles del campo aplaudiendo mientras la creación celebra la redención. Ezequiel 25:6 condena a Amón por aplaudir maliciosamente ante la destrucción de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110739, 'spa', 'Golpear o impedir', 'Golpear, herir o impedir, con aplicaciones que van desde el impacto físico hasta el castigo administrativo. Los contextos incluyen tanto el uso literal de golpear («hirió») como la restricción metafórica («detenga»). La visión de Daniel de la piedra que golpea la imagen hizo de este verbo un término significativo en la literatura apocalíptica como símbolo de la intervención divina contra los reinos humanos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110742, 'spa', 'Unión / costura textil', 'Punto o lugar de unión donde dos piezas textiles se acoplan, usado exclusivamente en la construcción del tabernáculo. En Éx 26:4-5 y 36:11-12, 17 designa la costura donde los paños de cortina se juntan para formar una cubierta continua. En Éx 28:27 y 39:20 describe el punto de acoplamiento de las hombreras del efod. Todo el vocabulario pertenece al registro técnico sacerdotal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110746, 'spa', 'Sartén o plancha', 'Plancha o sartén plana para preparar ofrendas de cereal. Levítico 2:5, 6:14 y 7:9 prescriben la minjá horneada en sartén como tipo de ofrenda distinto al preparado en olla honda. Primera Crónicas 23:29 incluye las tortas de sartén en el inventario del servicio levítico. En Ezequiel 4:3, el mismo término designa una plancha de hierro usada como muro simbólico de asedio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110748, 'spa', 'Ser borrado (pasivo)', 'Ser borrado (pasivo): sentido pasivo en Nifal de ser eliminado, borrado o destruido, expresando el resultado de la acción sobre el sujeto. En Génesis 7:23 ''todo ser viviente fue borrado''; Deuteronomio 25:6 busca evitar que un nombre ''sea borrado de Israel''; Salmo 69:28 ruega ''sean borrados del libro de los vivientes''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110750, 'spa', 'Borrar, eliminar un registro escrito, nombre o pecado', 'Borrar, eliminar un registro escrito, nombre o pecado: sentido activo en Qal de la eliminación metafórica. Dios declara ''borraré de mi libro al que haya pecado contra mí'' (Éx 32:33); la memoria de Amalec será borrada (Éx 17:14); en Isaías 43:25 Dios dice ''yo soy el que borro tus transgresiones''. El español ''borrar'' y ''borrarás'' reflejan consistentemente esta eliminación de lo registrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110751, 'spa', 'Limpiar, enjugar', 'Limpiar, enjugar: sentido activo en Qal de limpiar físicamente una superficie o enjugar humedad, el significado concreto y táctil original. En 2 Reyes 21:13 Dios limpia a Jerusalén ''como se limpia un plato, limpiándolo y volteándolo boca abajo''; Proverbios 30:20 describe a la adúltera que ''come y se limpia la boca''; Isaías 25:8 promete que Dios ''enjugará las lágrimas de todos los rostros''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110753, 'spa', 'Destruir (causativo)', 'Destruir (causativo): sentido causativo en Hifil de provocar destrucción u obliteración, intensificando el significado básico hacia la aniquilación activa. Nehemías 13:14 suplica ''no borres mis buenas obras''; Proverbios 31:3 advierte contra dar fuerza ''a las que destruyen reyes''; Jeremías 18:23 pide a Dios que no borre su pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110766, 'spa', 'Aniquilar, exterminar', 'Aniquilar, exterminar: sentido activo en Qal de eliminar seres vivos de la tierra, especialmente en el contexto del juicio divino mediante el Diluvio. Génesis 7:23 registra que Dios ''borró todo ser viviente de la faz de la tierra'', y Números 5:23 describe al sacerdote lavando maldiciones en el agua amarga para ''borrar'' las palabras escritas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110785, 'spa', 'Danza, baile', 'Danza comunitaria y festiva asociada con el gozo, la adoración y la reversión del dolor. El término aparece en dos contextos principales: la alabanza litúrgica, donde Israel es convocado a alabar al SEÑOR «con danza» acompañada de pandero y lira (Sal 149:3; 150:4), y contextos proféticos donde la danza simboliza el gozo restaurado. El Salmo 30:11 declara «cambiaste mi lamento en danza».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110791, 'spa', 'Visión reveladora', 'Experiencia visionaria mediante la cual llega la revelación divina, frecuentemente en un estado extático. Los contextos abarcan desde las promesas del pacto de Dios a Abram hasta los oráculos proféticos de Balaam y la condena de Ezequiel contra las visiones falsas. El término distingue este modo de revelación visual de la profecía auditiva, señalando momentos en los que lo divino irrumpe en lo visible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110792, 'spa', 'Ventana arquitectónica', 'Ventanas o aberturas para la entrada de luz en un edificio, específicamente en la arquitectura palaciega de Salomón. La frase repetida «ventana frente a ventana» sugiere una disposición simétrica diseñada para maximizar la luz natural. La raíz hebrea indica que su función principal era permitir la visión y la iluminación, destacando el cuidado estético del diseño del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110796, 'spa', 'Preservación de vida', 'Preservación o restauración de la vida, avivamiento. En Gn 45:5, José declara que Dios lo envió delante לְמִחְיָה, «para preservación de vida». Esdras 9:8-9 lo emplea dos veces para referirse a «un poco de alivio» en medio de la servidumbre. En 2 Cr 14:13 el uso se extiende a la supervivencia militar: no quedó en ellos vitalidad alguna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110798, 'spa', 'Carne viva (término levítico)', 'Carne viva o en carne viva visible en una lesión cutánea, término técnico de diagnóstico en el código de pureza levítico. En Lv 13:10 y 13:24 (מִחְיַת בָּשָׂר חַי), la forma constructa describe el tejido vivo expuesto bajo la piel enferma, señal de impureza. Las traducciones recurren universalmente a vocabulario clínico para expresar la vitalidad biológica que hace de esta carne un indicador diagnóstico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110799, 'spa', 'Sustento, medio de vida', 'Sustento material, alimento o medio de subsistencia: las provisiones concretas necesarias para la vida diaria. En Jue 6:4 los madianitas destruyeron todo sustento en Israel, y en Jue 17:10 designa el salario y las provisiones ofrecidas a un levita contratado. Se distingue del sentido más teológico de «preservación de vida» por su carácter estrictamente material y cotidiano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110803, 'spa', 'El precio monetario, costo o pago ofrecido a cambio de algo', 'El precio monetario, costo o pago ofrecido a cambio de algo: tierras, bienes, animales o servicios. Se usa concretamente para la compra de la era de David (2 Sam 24:24), el comercio de caballos de Salomón (1 Rey 10:28; 2 Cr 1:16) y la oferta por la viña de Nabot (1 Rey 21:2). Se extiende figuradamente al ''precio'' incalculable de la sabiduría (Job 28:15; Prov 17:16), la gracia sin costo de la bendición divina (Isa 55:1) y la venta de Israel ''sin precio'' (Sal 44:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110810, 'spa', 'Nombre propio femenino', 'Nombre propio femenino de una hija de Zelofehad, de la tribu de Manasés, que aparece en las narrativas de herencia de Números 26:33, 27:1, 36:11 y Josué 17:3. La LXX lo refleja como Maala. El nombre podría derivar de una raíz que significa ''enfermedad'' o ''debilidad'', aunque su etimología exacta es debatida. También se aplica a un personaje galaadita en 1 Crónicas 7:18.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110812, 'spa', 'Enfermedad física', 'Enfermedad o dolencia física en sentido general, sin especificar padecimientos concretos. Los contextos vinculan la enfermedad con la acción divina, ya sea como algo que Dios previene como bendición o permite como juicio. La frase «yo soy el Señor, tu sanador» en Éxodo 15:26 establece el fundamento teológico de la sanidad como atributo divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110813, 'spa', 'Danza, baile en corro', 'Danza o baile en corro, generalmente ejecutado de forma comunitaria en celebración gozosa. Aparece en festejos por victorias (Éx 15:20, danza de Miriam con panderos; Jue 11:34, la hija de Jefté; 1 S 18:6; 29:5), en reuniones festivas (Jue 21:21, las jóvenes de Silo), en culto idolátrico (Éx 32:19, el becerro de oro) y como imagen de belleza y gracia (Cnt 7:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110819, 'spa', 'Nombre propio masculino', 'Nombre propio del hijo de Elimélec y Noemí, primer esposo de Rut. Las evidencias multilingües preservan el nombre con variaciones fonéticas menores (Mahlon, Majlón, Machlon). Su importancia radica no en sus hechos sino en su muerte, que generó las circunstancias para la lealtad extraordinaria de Rut y para el linaje que conduciría al rey David y, finalmente, al Mesías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110820, 'spa', 'Mahli (nombre personal)', 'Nombre personal levítico portado por al menos dos individuos. El Mahli principal es hijo de Merari y nieto de Leví, ancestro del clan mahlita encargado de transportar los componentes estructurales del tabernáculo (Éx 6:19; Núm 3:20, 33; 4:29-33). Su genealogía se traza en 1 Crónicas 6:4, 29; 23:21, 23; 24:26-28. Un segundo Mahli es hijo de Musi (1 Cr 6:32; 23:23; 24:30), lo que lo hace sobrino y homónimo del primero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110828, 'spa', 'División o turno rotativo, especialmente de sacerdotes y levitas que servían en ', 'División o turno rotativo, especialmente de sacerdotes y levitas que servían en el templo por turnos programados. Este es el uso dominante (41 apariciones), concentrado en 1 Crónicas 23-27 y 2 Crónicas. La evidencia multilingüe converge en división/división/Abteilung. Pasajes clave incluyen la organización davídica de los turnos levíticos (1 Cr 23:6; 24:1) y las divisiones militares mensuales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110839, 'spa', 'Porción o parte asignada como herencia, con énfasis en el resultado distributivo', 'Porción o parte asignada como herencia, con énfasis en el resultado distributivo más que en la estructura organizativa. Atestiguado en Ezequiel 48:29, donde el profeta describe la redistribución escatológica de la tierra. El español ''sus porciones'' destaca el cambio de agrupación organizativa a la parte misma que se recibe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110849, 'spa', 'Objeto de deseo o deleite', 'Objeto de deseo o deleite: aquello que se anhela, se aprecia o se encuentra profundamente deseable, aplicado a personas y a la cualidad abstracta de la deseabilidad misma. La aparición más notable es Cantares 5:16, donde el amado es descrito como כֻּלּוֹ מַחֲמַדִּים (''todo él es delicia''), un plural intensivo sin paralelo real en español. La esposa de Ezequiel es ''el deseo de tus ojos'' (Ez 24:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110850, 'spa', 'Cosas preciosas, tesoros o posesiones valiosas', 'Cosas preciosas, tesoros o posesiones valiosas: objetos concretos de valor, frecuentemente en contextos de pérdida, saqueo o destrucción. Cuando Nabucodonosor destruye el templo, ''todos sus vasos preciosos'' (כָּל כְּלֵי מַחְמָד) son quemados (2 Cr 36:19). Lamentaciones describe dos veces los מַחֲמַדִּים de Jerusalén: su pueblo cambia sus tesoros por comida (Lam 1:11) y extranjeros entran al santuario para apoderarse de ellos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110862, 'spa', 'campamento', 'Campamento o asentamiento temporal: la acepción dominante con 212 apariciones. Abarca el campamento israelita del desierto alrededor del tabernáculo (Éx 16:13; 19:17; 32:26-27), los campamentos militares antes de la batalla (Jos 10:5; Jue 7:15; 1 S 4:3) y los campamentos de caravanas (Gn 32:8, 21). Funciona como espacio físico y como frontera social y sagrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110885, 'spa', 'ejército acampado', 'Por metonimia, el ejército o hueste militar acampada en un lugar: 3 apariciones donde el término se refiere no al emplazamiento físico sino a la fuerza combatiente. En 2 Cr 14:13 los etíopes son derrotados ''ante su campamento'' (su ejército); Sal 27:3 declara ''aunque un ejército acampe contra mí''; Ez 1:24 compara un sonido al ''estruendo de un ejército''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110904, 'spa', 'campamento dual simbólico', 'Campamento dual en contexto poético-simbólico: una única aparición en Cnt 6:13 referida a ''la danza de los dos campamentos'' (כִּמְחֹלַת הַמַּחֲנָיִם). La forma dual evoca el topónimo Mahanaim (''dos campamentos'', Gn 32:2, donde Jacob nombró el lugar tras encontrar el campamento angélico junto al suyo). La interpretación es debatida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110909, 'spa', 'El topónimo Mahanaim (מַחֲנַיִם, ''dos campamentos''), una ciudad al este del Jord', 'El topónimo Mahanaim (מַחֲנַיִם, ''dos campamentos''), una ciudad al este del Jordán en la región de Galaad. Nombrada por Jacob en su encuentro angélico (Gn 32:2), aparece en las descripciones de límites tribales (Jos 13:26, 30), las listas de ciudades levíticas (Jos 21:38; 1 Cr 6:65) y en relatos históricos como sede del reino rival de Is-boset (2 Sam 2:8, 12, 29) y refugio de David durante la rebelión de Absalón (2 Sam 17:24, 27; 19:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110918, 'spa', 'Refugio, amparo', 'Refugio, amparo: lugar de protección, resguardo o puerto seguro — usado concretamente para la cobertura física contra la tormenta y la lluvia (Job 24:8; Is 4:6; 25:4), de peñascos rocosos que cobijan a los damanes (Sal 104:18), y metafóricamente de la falsedad como refugio engañoso (Is 28:15, 17). El uso bíblico dominante, sin embargo, es teológico: Dios como el refugio personal del fiel, atestiguado en casi todas las apariciones en los Salmos con posesivos como ''mi refugio'' y ''nuestro refugio.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110927, 'spa', 'Necesidad, carencia o pobreza', 'Necesidad, carencia o pobreza: el estado de ser materialmente deficiente, abarcando desde una cosa específica que se necesita (Dt 15:8, ''suficiente para su necesidad'') hasta la ausencia general de lo necesario (Jue 18:10; 19:19-20, ''no falta de nada''; Sal 34:9, ''los que le temen no tienen carencia'') y la indigencia absoluta (Prov 6:11; 11:24; 14:23; 21:5, 17; 22:16; 24:34; 28:27, donde se usa como sinónimo de רֵישׁ, ''pobreza''). Proverbios lo emplea como advertencia moral contra la pereza y la imprudencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110934, 'spa', 'Destrozar, aplastar', 'Destrozar, aplastar: destruir con fuerza abrumadora, reduciendo al objetivo a ruinas. Este sentido enfatiza la destrucción total. Dios destroza cabezas (Sal 68:21), aplasta los lomos de los adversarios (Dt 33:11) y el rey davídico destroza reyes en el día de la ira (Sal 110:5). El oráculo de Balaam usa esta imagen para la conquista de naciones enteras (Nm 24:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110935, 'spa', 'Golpear, herir', 'Golpear, herir: asestar un golpe poderoso, con énfasis en el acto de golpear más que en el grado de destrucción. Jael golpeó la cabeza de Sísara con una estaca de tienda (Jue 5:26), y Job reconoce que Dios hiere pero sus manos también sanan (Job 5:18). En Job 26:12 Dios golpea al monstruo marino Rahab, combinando fuerza física con autoridad cósmica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110936, 'spa', 'Traspasar, penetrar', 'Traspasar, penetrar: atravesar un objetivo, enfatizando que el golpe llega a lo profundo o lo traspasa. El oráculo de Balaam declara que las flechas de Israel traspasan a las naciones enemigas (Nm 24:8), y el Salmo 68:23 evoca pies bañados en sangre de enemigos traspasados. La imagen pasa del impacto superficial a la penetración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110939, 'spa', 'Herir, lesionar', 'Herir, lesionar: causar herida o daño corporal, con el foco desplazado del acto de golpear hacia el daño infligido. En el Cántico de Moisés (Dt 32:39), Dios declara ''Yo hiero y yo sano'', emparejando מָחַץ con la sanación para resaltar la herida como resultado central, dentro del contexto teológico de la soberanía divina sobre la vida y la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110948, 'spa', 'Piedra labrada', 'Las traducciones identifican piedra cortada o de cantera: español ''cantera''. Segundo Reyes 12:12 y 22:6 registran la compra de piedras labradas para las reparaciones del templo bajo Joás y Josías respectivamente, emparejadas con madera en ambos relatos. Segundo Crónicas 34:11 ofrece el paralelo del relato de Josías. La asociación constante con madera demuestra que eran materiales de construcción fundamentales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110950, 'spa', 'Mitad (porción)', 'Mitad (porción): una mitad de un todo, usada en estado constructo o con sufijos pronominales para especificar lo que se divide. Aplicada al impuesto de expiación del medio siclo para el censo (Éx 30:13, 15; 38:26), la división equitativa del botín de guerra entre combatientes y asamblea (Nm 31:29, 30, 42, 47), las designaciones territoriales de media tribu (Jos 21:25; 1 Cr 6:46, 55) y el mando de la mitad de los carros de Zimri (1 R 16:9). En Neh 8:3 aparece con el sentido relacionado de ''punto medio'' del día.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110959, 'spa', 'mañana (adverbio temporal)', 'mañana (adverbio temporal)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110966, 'spa', 'Sustantivo temporal que indica el día inmediatamente posterior a un punto de ref', 'Sustantivo temporal que indica el día inmediatamente posterior a un punto de referencia narrativo o calendárico. En la narrativa, mimochorat (''al día siguiente'') avanza la trama hacia la mañana siguiente de eventos decisivos: la destrucción de Sodoma (Gn 19:34), el becerro de oro (Éx 32:30), la muerte de Saúl (1 S 31:8). En contextos litúrgicos, ''el día siguiente del sábado'' (Lv 23:11, 15-16) y ''el día siguiente de la Pascua'' establecen un calendario ritual preciso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110976, 'spa', 'planes, propósitos, intenciones', 'planes, propósitos, intenciones');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110978, 'spa', 'maquinaciones, tramas malvadas', 'maquinaciones, tramas malvadas');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110979, 'spa', 'diseño inventivo, artesanía', 'diseño inventivo, artesanía');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (110980, 'spa', 'pensamientos, reflexiones internas', 'pensamientos, reflexiones internas');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111010, 'spa', 'Tinieblas, lugar oscuro', 'Lugar oscuro o región de tinieblas en contextos poéticos elevados. Abarca extensiones metafóricas: escondrijos de violencia (Sal 74:20), el sombrío reino de la muerte y el Seol (Sal 88:6, 18; 143:3; Lam 3:6), ocultamiento de tramas perversas (Isa 29:15) y desorientación que Dios promete disipar (Isa 42:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111018, 'spa', 'Nombre propio levítico', 'Este nombre propio aparece transliterado como ''Majat'' en las versiones en español. Primer Crónicas 6:35 lo sitúa en una genealogía levítica. Segundo Crónicas 29:12 lo identifica como uno de los levitas coatitas que respondieron al llamado de Ezequías para consagrar el templo tras años de abandono. Segundo Crónicas 31:13 lo incluye entre los oficiales que supervisaban las ofrendas del templo durante las reformas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111019, 'spa', 'Ruina, destrucción', 'Ruina o destrucción como consecuencia de la necedad, la maldad o la pobreza — tema dominante en Proverbios. La boca del necio es su propia ruina (Prov 10:14; 13:3; 18:7), la pobreza arruina al pobre (Prov 10:15) y sin pueblo el príncipe enfrenta ruina (Prov 14:28). El Salmo 89:40 extiende este sentido a la devastación de fortalezas. La palabra funciona como resultado inevitable de la insensatez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111022, 'spa', 'Terror, objeto de espanto', 'Terror u objeto de espanto, usado en contextos proféticos de juicio divino. Isaías 54:14 promete a la Sion restaurada que estará lejos del terror (מְחִתָּה), emparejado con opresión (עֹשֶׁק). Jeremías 17:17 suplica a Dios que no sea terror para el profeta, y Jeremías 48:39 declara a Moab objeto de espanto y burla. No es ruina pasiva, sino pavor activo que paraliza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111028, 'spa', 'Incensario portátil específicamente para transportar brasas encendidas e inciens', 'Incensario portátil específicamente para transportar brasas encendidas e incienso en el ritual sacerdotal. Este sentido domina los relatos de Levítico y Números: Nadab y Abiú tomaron cada uno ''su incensario'' para ofrecer fuego extraño (Lv 10:1), el sumo sacerdote lleva un incensario al Lugar Santísimo en el Día de la Expiación (Lv 16:12), y los 250 rebeldes llevan uno cada uno en el episodio de Coré (Nm 16:6, 17-18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111029, 'spa', 'Brasero, platillo o bandeja usada en el mantenimiento rutinario del tabernáculo,', 'Brasero, platillo o bandeja usada en el mantenimiento rutinario del tabernáculo, ya sea como platillo de oro para recortar las mechas del candelabro (Éx 25:38; 37:23; Nm 4:9), o como recipiente de bronce asociado al altar del holocausto (Éx 27:3; 38:3; Nm 4:14). También aparece como utensilios de oro en el templo de Salomón (1 R 7:50; 2 Cr 4:22) y entre los objetos llevados al exilio babilónico (2 R 25:15; Jer 52:19).');